/**
 * @fileoverview Test the usage of a private Class
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-private-class-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-private-class-usage', rule, {

    valid: [

    ],

    invalid: [
        {
            settings: {
                extjs: {
                    version: '7.9.0'
                }
            },
            code: `
                // example of extending a private class
                var MyCustomClass = Ext.extend(Ext.AbstractManager, {
                    customProp: true
                });
                // example of extending a private class using Ext.define()
                Ext.define('MyCustomClass', {
                    extend: 'Ext.AnimationQueue',
                    constructor: function () {
                        this.flyEl = new Ext.util.Fly();
                        Ext.app.Util.addNamespaces('ABC');
                        this.callParent();
                    }
                });
                // example using xclass
                Ext.create({ xclass: 'Ext.util.GroupCollection' });
                // example passing class name as a string
                Ext.create('Ext.util.Bag', {});

                // new 7.4 private classes
                Ext.create('Ext.grid.AdvancedGroupStore');
                Ext.create('Ext.grid.feature.AdvancedGroupStore');
                Ext.create('Ext.grid.plugin.BaseFilterBar');
                Ext.create('Ext.grid.plugin.BaseGroupingPanel');
                Ext.create('Ext.grid.plugin.BaseSummaries');
                Ext.create('Ext.grid.plugin.filterbar.filters.SingleFilter');
                Ext.create('Ext.grid.plugin.grouping.Column');
                Ext.create('Ext.grid.plugin.grouping.DragZone');
                Ext.create('Ext.grid.plugin.grouping.DropZone');
                Ext.create('Ext.grid.cell.Group');
            `,
            errors: [
                { 
                    message: /Usage of private Class 'Ext.AbstractManager' found.*/,
                    type: 'MemberExpression'
                },
                { 
                    message: /Usage of private Class 'Ext.AnimationQueue' found.*/,
                    type: 'Property'
                },
                { 
                    message: /Usage of private Class 'Ext.util.Fly' found.*/,
                    type: 'NewExpression'
                },
                { 
                    message: /Usage of private Class 'Ext.app.Util' found.*/,
                    type: 'MemberExpression'
                },
                { 
                    message: /Usage of private Class 'Ext.util.GroupCollection' found.*/,
                    type: 'Property'
                },
                { 
                    message: /Usage of private Class 'Ext.util.Bag' found.*/,
                    type: 'MemberExpression'
                },
                
                // new 7.4 private classes
                { message: /Usage of private Class 'Ext.grid.AdvancedGroupStore' found.*/ },
                { message: /Usage of private Class 'Ext.grid.feature.AdvancedGroupStore' found.*/ },
                { message: /Usage of private Class 'Ext.grid.plugin.BaseFilterBar' found.*/ },
                { message: /Usage of private Class 'Ext.grid.plugin.BaseGroupingPanel' found.*/ },
                { message: /Usage of private Class 'Ext.grid.plugin.BaseSummaries' found.*/ },
                { message: /Usage of private Class 'Ext.grid.plugin.filterbar.filters.SingleFilter' found.*/ },
                { message: /Usage of private Class 'Ext.grid.plugin.grouping.Column' found.*/ },
                { message: /Usage of private Class 'Ext.grid.plugin.grouping.DragZone' found.*/ },
                { message: /Usage of private Class 'Ext.grid.plugin.grouping.DropZone' found.*/ }
            ]
        }
    ]
});
